public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer MAX_ATTEMPTS = 2; // initial request + one retry on 503
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('[A-Z]{3}');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normalise(baseCurrency);
        if (!isValidCurrencyCode(base)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        List<String> quotes = new List<String>();
        for (String quote : quoteCurrencies) {
            String normalisedQuote = normalise(quote);
            if (!isValidCurrencyCode(normalisedQuote)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            quotes.add(normalisedQuote);
        }

        HttpResponse response = sendWithRetry(base, quotes);

        Integer status = response.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Exchange rate request failed with status code ' + status);
        }

        return parseRates(response.getBody(), quotes);
    }

    private static HttpResponse sendWithRetry(String base, List<String> quotes) {
        HttpResponse response;
        for (Integer attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            response = send(base, quotes);
            if (response.getStatusCode() != 503 || attempt == MAX_ATTEMPTS) {
                return response;
            }
        }
        return response;
    }

    private static HttpResponse send(String base, List<String> quotes) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT
            + '?base=' + base
            + '&symbols=' + String.join(quotes, ','));
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(120000);
        return new Http().send(request);
    }

    private static Map<String, Decimal> parseRates(String body, List<String> quotes) {
        Map<String, Object> root;
        try {
            root = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response body.');
        }

        if (root == null || !(root.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unable to parse exchange rate response body.');
        }

        Map<String, Object> rates = (Map<String, Object>) root.get('rates');
        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String quote : quotes) {
            Object rateValue = rates.get(quote);
            if (rateValue == null) {
                throw new ExchangeRateException('Missing rate for requested currency ' + quote);
            }
            try {
                result.put(quote, toDecimal(rateValue));
            } catch (Exception e) {
                throw new ExchangeRateException('Unable to parse rate for currency ' + quote);
            }
        }

        return result;
    }

    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        return Decimal.valueOf(String.valueOf(value));
    }

    private static String normalise(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    private static Boolean isValidCurrencyCode(String code) {
        return code != null && CURRENCY_PATTERN.matcher(code).matches();
    }
}
