public inherited sharing class OpportunityWinService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != STAGE_CLOSED_WON) {
                opp.StageName = STAGE_CLOSED_WON;
                opp.CloseDate = Date.today();
                opportunitiesToClose.add(opp);
            }
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.registerDirty(opportunitiesToClose);

        List<Deal_Won__e> dealWonEvents = new List<Deal_Won__e>();
        for (Opportunity opp : opportunitiesToClose) {
            Deal_Won__e event = new Deal_Won__e();
            event.Opportunity_Id__c = opp.Id;
            event.Amount__c = opp.Amount;
            dealWonEvents.add(event);
        }
        uow.registerPublish(dealWonEvents);

        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
